const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');

// Custom input validation for search queries
const SEARCH_PATTERN = /^([a-zA-Z0-9]+\s?)*\.$/ // Validates "words ending with period"

// Additional patterns for different field types
const EMAIL_PATTERN = /^([a-zA-Z0-9_.+-]+)@([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$/
const TAG_PATTERN = /^([a-zA-Z0-9]+,?\s?)*$/

function validateSearchInput(input) {
  if (!input || input.length > 500) return false;
  return SEARCH_PATTERN.test(input);
}

function validateEmail(input) {
  if (!input || input.length > 254) return false;
  return EMAIL_PATTERN.test(input);
}

function validateTags(input) {
  if (!input || input.length > 200) return false;
  return TAG_PATTERN.test(input);
}

const typeDefs = gql`
  type SearchResult {
    id: ID!
    title: String!
    snippet: String
    relevance: Float
  }

  type User {
    id: ID!
    email: String!
    name: String
  }

  type Query {
    search(query: String!, tags: String): [SearchResult!]!
    findUser(email: String!): User
    healthCheck: String!
  }
`;

const resolvers = {
  Query: {
    search: async (_, { query, tags }) => {
      // Validate search query format
      if (!validateSearchInput(query)) {
        throw new Error('Invalid search query format. Must be words ending with a period.');
      }

      // Validate optional tags
      if (tags && !validateTags(tags)) {
        throw new Error('Invalid tags format.');
      }

      // Simulated search logic
      return [
        { id: '1', title: `Result for: ${query}`, snippet: 'Sample result...', relevance: 0.95 },
      ];
    },
    findUser: async (_, { email }) => {
      if (!validateEmail(email)) {
        throw new Error('Invalid email format.');
      }
      // Simulated user lookup
      return { id: '42', email, name: 'Test User' };
    },
    healthCheck: () => 'OK',
  },
};

const app = express();

// Rate limiting per IP (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) {
    return res.status(429).json({ error: 'Rate limited' });
  }
  requestCounts.set(ip, count + 1);
  next();
});

// Reset counts every minute
setInterval(() => requestCounts.clear(), 60000);

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  plugins: [
    {
      requestDidStart() {
        return {
          didResolveOperation({ request }) {
            // Log query complexity metrics
            console.log(`Operation: ${request.operationName || 'anonymous'}`);
          },
        };
      },
    },
  ],
});

async function startServer() {
  await server.start();
  server.applyMiddleware({ app, path: '/graphql' });

  const PORT = process.env.PORT || 4000;
  app.listen(PORT, () => {
    console.log(`GraphQL server running at http://localhost:${PORT}${server.graphqlPath}`);
  });
}

startServer();
